" r="10"></circle></svg>حداقل ۲ سال سابقه فنی الکترونیک/برق</span></div><h4 class="text-[17px] font-black text-slate-900">کارشناس فنی خدمات پس از فروش و کنترل کیفیت (QC)</h4><div class="mt-2 flex items-center gap-1.5 text-[12.5px] font-semibold text-slate-500"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-map-pin h-4 w-4 text-emerald-600" aria-hidden="true"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"></path><circle cx="12" cy="10" r="3"></circle></svg><span>اصفهان (کارخانه مرکزی)</span></div><div class="mt-5 border-t border-slate-100 pt-4"><div class="mb-2.5 text-[12.5px] font-extrabold text-slate-800">مهارت‌ها و شرایط احراز:</div><ul class="space-y-2"><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check mt-1 h-4 w-4 shrink-0 text-emerald-600" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>عیب‌یابی بردهای درایور LED، پاورهای سوئیچینگ و کنترلرهای پیکسلی</span></li><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check mt-1 h-4 w-4 shrink-0 text-emerald-600" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>انجام تست‌های استاندارد IP67 / IP68 و کنترل کیفیت نهایی پیش از ارسال</span></li><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check mt-1 h-4 w-4 shrink-0 text-emerald-600" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>پاسخگویی فنی و راهنمایی تلفنی پیمانکاران و کارفرمایان</span></li></ul></div></div><a href="#apply-form" class="mt-6 inline-flex items-center justify-center rounded-xl bg-emerald-50 px-4 py-3 text-[13px] font-extrabold text-emerald-900 transition-colors hover:bg-emerald-700 hover:text-white">ارسال رزومه برای این موقعیت</a></article></div></div><div data-recruit-tab-panel="accounting" class="hidden"><div class="mb-8 rounded-2xl border border-emerald-100 bg-emerald-50/50 p-6"><div class="flex flex-wrap items-center justify-between gap-3"><div><span class="rounded-lg bg-emerald-700 px-3 py-1 text-[11px] font-extrabold text-white">مالی، بهای تمام‌شده و ستاد</span><h3 class="mt-2.5 text-xl font-black text-slate-900">واحد حسابداری و مالی</h3></div></div><p class="mt-2.5 text-[14px] leading-8 text-slate-600">واحد مالی و حسابداری وظیفه مدیریت حسابداری صنعتی، محاسبه بهای تمام‌شده تولید، امور مالیاتی و مدیریت قراردادهای پیمانکاری شهرداری‌ها و سامانه ستاد را بر عهده دارد.</p></div><div class="grid gap-6 md:grid-cols-2"><article class="card-light flex flex-col justify-between rounded-[1.75rem] border border-slate-200/90 bg-white p-6"><div><div class="mb-4 flex flex-wrap items-center gap-2 text-[11.5px] font-bold"><span class="inline-flex items-center gap-1 rounded-lg bg-emerald-50 px-2.5 py-1 text-emerald-800"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-briefcase h-3.5 w-3.5" aria-hidden="true"><path d="M16 20V4a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path><rect width="20" height="14" x="2" y="6" rx="2"></rect></svg>تمام‌وقت — حضوری</span><span class="inline-flex items-center gap-1 rounded-lg bg-slate-100 px-2.5 py-1 text-slate-700"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-clock h-3.5 w-3.5" aria-hidden="true"><path d="M12 6v6l4 2"></path><circle cx="12" cy="12" r="10"></circle></svg>حداقل ۴ سال سابقه حسابداری تولیدی</span></div><h4 class="text-[17px] font-black text-slate-900">کارشناس ارشد حسابداری صنعتی و پیمانکاری</h4><div class="mt-2 flex items-center gap-1.5 text-[12.5px] font-semibold text-slate-500"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-map-pin h-4 w-4 text-emerald-600" aria-hidden="true"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"></path><circle cx="12" cy="10" r="3"></circle></svg><span>اصفهان (شهرک صنعتی برق و الکترونیک)</span></div><div class="mt-5 border-t border-slate-100 pt-4"><div class="mb-2.5 text-[12.5px] font-extrabold text-slate-800">مهارت‌ها و شرایط احراز:</div><ul class="space-y-2"><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check mt-1 h-4 w-4 shrink-0 text-emerald-600" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>تسلط بر حسابداری بهای تمام‌شده، انبار و اموال در شرکت‌های تولیدی</span></li><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check mt-1 h-4 w-4 shrink-0 text-emerald-600" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>آشنایی کامل با سامانه مودیان، قوانین مالیات بر ارزش افزوده و بیمه پیمان‌ها</span></li><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-check mt-1 h-4 w-4 shrink-0 text-emerald-600" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><path d="m9 12 2 2 4-4"></path></svg><span>تجربه کار با سامانه تدارکات الکترونیکی دولت (ستاد) و صورت‌وضعیت‌نویسی</span></li></ul></div></div><a href="#apply-form" class="mt-6 inline-flex items-center justify-center rounded-xl bg-emerald-50 px-4 py-3 text-[13px] font-extrabold text-emerald-900 transition-colors hover:bg-emerald-700 hover:text-white">ارسال رزومه برای این موقعیت</a></article></div></div><div data-recruit-tab-panel="it" class="hidden"><div class="mb-8 rounded-2xl border border-emerald-100 bg-emerald-50/50 p-6"><div class="flex flex-wrap items-center justify-between gap-3"><div><span class="rounded-lg bg-emerald-700 px-3 py-1 text-[11px] font-extrabold text-white">نرم‌افزار، وب و شبکه</span><h3 class="mt-2.5 text-xl font-black text-slate-900">واحد فناوری اطلاعات (IT) و دیجیتال</h3></div></div><p class="mt-2.5 text-[14px] leading-8 text-slate-600">واحد IT مسئول توسعه اپلیکیشن‌های موبایلی کنترل هوشمند المان‌ها، نگهداری زیرساخت شبکه کارخانه و مدیریت پلتفرم فروش آنلاین و محتوای دیجیتال شرکت است.</p></div><div class="grid gap-6 md:grid-cols-2"><article class="card-light flex flex-col justify-between rounded-[1.75rem] border border-slate-200/90 bg-white p-6"><div><div class="mb-4 flex flex-wrap items-center gap-2 text-[11.5px] font-bold"><span class="inline-flex items-center gap-1 rounded-lg bg-emerald-50 px-2.5 py-1 text-emerald-800"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-briefcase h-3.5 w-3.5" aria-hidden="true"><path d="M16 20V4a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path><rect width="20" height="14" x="2" y="6" rx="2"></rect></svg>تمام‌وقت / پروژه‌ای</span><span class="inline-flex items-center gap-1 rounded-lg bg-slate-100 px-2.5 py-1 text-slate-700"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-clock h-3.5 w-3.5" aria-hidden="true"><path d="M12 6v6l4 2"></path><circle cx="12" cy="12" r="10"></circle></svg>حداقل ۲ سال سابقه توسعه موبایل</span></div><h4 class="text-[17px] font-black text-slate-900">توسعه‌دهنده اپلیکیشن موبایل و اینترنت اشیاء (IoT)</h4><div class="mt-2 flex items-center gap-1.5 text-[12.5px] font-semibold text-slate-500"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-map-pin h-4 w-4 text-emerald-600" aria-hidden="true"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"></path><circle cx="12" cy="10" r="3"></circle></svg><span>اصفهان</span></div><div class="mt-5 border-t border-slate-100 pt-4"><div class="mb-2.5 text-[12.5px] font-extrabold text-slate-800">مهارت‌ها و شرایط احراز:</div><ul class="space-y-2"><li class="flex items-start gap-2 text-[13px] leading-6 text-slate-600"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-